function escape(s=''){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function splitAssistantReply(value=''){
 const normalized=String(value).replace(/\r/g,'').replace(/\*\*/g,'').replace(/([。！？；：:])\s+(?=\d+[.、]\s*)/g,'$1\n').trim();
 const sections=normalized.split(/\n{2,}|\n(?=\s*(?:\d+[.、]|[-•]))/).map(x=>x.trim()).filter(Boolean),chunks=[];
 for(const section of sections){
  if(section.length<=260){chunks.push(section);continue}
  const sentences=section.match(/[^。！？；]+[。！？；]?/g)||[section];let current='';
  for(const sentence of sentences){if(current&&current.length+sentence.length>240){chunks.push(current.trim());current=''}current+=sentence}
  if(current.trim())chunks.push(current.trim());
 }
 return chunks.length?chunks:[normalized];
}
function chatMessageHtml(message){
 const text=String(message.content||'').trim(),match=text.match(/^(\d+)[.、]\s*([^：:]{2,24})[：:]\s*([\s\S]*)$/);
 if(message.role==='assistant'&&match)return `<strong class="bubble-title">${escape(match[1])}. ${escape(match[2])}</strong><span>${escape(match[3])}</span>`;
 return `<span>${escape(text)}</span>`;
}
function toast(msg){toastEl.textContent=msg;toastEl.classList.add('show');setTimeout(()=>toastEl.classList.remove('show'),2200)}
function api(path,opts={}){return fetch(path,{...opts,headers:{'Content-Type':'application/json',...(state.token?{Authorization:`Bearer ${state.token}`}:{})}}).then(async r=>{const d=await r.json();if(!r.ok)throw new Error(d.error||'请求失败');return d;});}
