function providerPreview(action){
 const match=action.providers?.[0];
 if(!match)return `<div class="provider-empty"><b>专业支持建议</b><p>正在扩充能够承接这项需求的服务商，你仍可先查看行动要求。</p></div>`;
 const p=match.provider,name=p['服务商简称']||p['服务商名称']||'服务商',type=p['服务商类型']||p['机构类型']||'专业服务机构',intro=p['服务商简介']||p['机构简介']||p['简介']||'点击查看服务商的完整资料。',unique=v=>[...new Set(Array.isArray(v)?v:v?[v]:[])],services=unique(p['可提供服务']).slice(0,4),languages=unique(p['服务语言']).slice(0,3),methods=unique(p['办理方式']||p['服务方式']||p['是否支持远程办理']).slice(0,2),more=Math.max(0,(action.providers?.length||0)-1);
 return `<div class="provider-recommendation"><button class="figma-provider" data-provider-id="${escape(p.recordId)}"><span class="provider-banner">${escape(name)}</span><span class="provider-body"><b>${escape(type)}</b><span class="provider-intro">${escape(intro)}</span>${services.length?`<span class="provider-meta"><strong>可提供服务</strong><i>${services.map(x=>`<em>${escape(x)}</em>`).join('')}</i></span>`:''}${languages.length?`<span class="provider-meta"><strong>服务语言</strong><i>${languages.map(x=>`<em>${escape(x)}</em>`).join('')}</i></span>`:''}${methods.length?`<span class="provider-meta"><strong>办理方式</strong><i>${methods.map(x=>`<em>${escape(x)}</em>`).join('')}</i></span>`:''}<span class="provider-open" aria-hidden="true">→</span></span></button><button class="more-providers" data-action="service-toast">更多推荐${more?`（${more}）`:''}<span>→</span></button></div>`
}
