const guideDescriptions={
  '在香港开设业务':'了解在香港设立企业、开展业务及落地经营前需要准备的事项。','如何办理新公司的注册':'了解香港公司的注册流程、所需文件和基本要求。','本地私人公司周年申报表':'了解私人公司周年申报的时限、费用和提交要求。','注册成立本地有限公司常见问题':'集中了解本地有限公司注册时常见的问题与处理方式。','公司注册处主要收费':'查看公司注册、文件提交及相关服务的官方收费。','创业：牌照、注册及法例':'了解创业可能涉及的牌照、登记和法规要求。','香港的开放营商环境':'了解香港的营商制度、市场环境和企业支持。','借助香港走向全球':'了解企业如何利用香港连接国际市场和商业网络。','香港的连接优势':'了解香港在市场、资金、专业服务和国际网络方面的连接能力。','在香港设立企业及投资':'了解在香港设立企业和开展投资的基础信息。','在香港营商':'了解企业在香港经营涉及的主要政府服务和要求。','商业登记及公司注册':'了解商业登记与公司注册的区别、流程和官方入口。',
  '香港公司成立前后，需要准备哪些事项':'了解公司注册、商业登记、公司架构及开户前准备。','公司成立后，为什么要备存重要控制人登记册':'了解重要控制人的识别、登记册及指定代表要求。','开始经营后，需要保留哪些业务资料':'了解收入、付款、发票、银行结单及业务纪录要求。','香港公司成立后，如何开始实际经营':'了解商业登记、公司架构、银行账户及营商准备。','私人公司什么时候需要提交周年申报表':'了解NAR1、申报时限、费用及提交方法。','还没有收入，也要准备会计记录吗':'了解公司开展业务后需要持续保存的基本纪录。','香港公司的年度维护事项有哪些':'了解周年申报、公司资料和提交时限。','业务单据和会计记录需要保存多久':'了解业务纪录类型及保存要求。','香港公司如何通过商业税务网站报税':'了解利得税电子报税流程及所需文件。','周年申报逾期会发生什么':'了解申报期限、费用和逾期影响。','香港公司需要保存哪些会计和业务资料':'了解发票、收据、银行结单、收入及开支记录。','利得税报税表需要准备哪些材料':'了解财务报表、税项计算表及相关附件。','如何确认周年申报是否需要尽快处理':'了解私人公司周年申报期限和提交要求。','香港公司如何处理利得税电子申报':'了解电子报税入口、流程及提交文件。','如何查询业务是否需要香港牌照':'查询业务所需牌照、许可证、证书及批准要求。','香港公司申请撤销注册需要满足什么条件':'了解不营运、有偿债能力、债务和法律程序等条件。','撤销公司前为什么需要税务局不反对通知书':'了解不反对通知书的作用、申请人及基本程序。','如何申请不反对撤销公司注册通知书':'了解申请方式、处理程序及税务事项要求。'
};
function practicalInfo(type='pre-hk',conclusion=''){const inHK=type==='in-hk',items=(inHK?inGuides[conclusion]:preGuides[conclusion])||(inHK?inGuides['成立待运营']:preGuides['适合启动']);const subtitle=inHK?'根据你的在港评估结论，为你整理当前阶段值得先了解的实用内容。':({'适合启动':'开始落地前，这些流程和持续义务值得提前了解。','具备基础':'这些内容可以帮助你进一步确认注册要求、成本和合规事项。','值得探索':'先了解香港的营商环境和连接优势，再判断能否为业务带来实际价值。','早期准备':'从基础信息开始，了解在香港设立和经营企业需要考虑什么。'}[conclusion]||'从官方信息开始，了解在香港设立和经营企业需要考虑什么。');return `<section class="practical-info"><div class="practical-heading"><div><h2>${inHK?'你的在港经营指南信息':'你的赴港指南信息'}</h2></div></div><p class="practical-subtitle">${subtitle}</p><div class="practical-list">${items.map((x,i)=>`<button type="button" data-guide-type="${type}" data-guide-conclusion="${escape(conclusion)}" data-guide-index="${i}"><img class="guide-art" src="/assets/${['guide-prepare.svg','guide-tcsp.svg','guide-annual.svg'][i]}" alt=""><span><b>${x[0]}</b><small>${x[1]}</small></span></button>`).join('')}</div></section>`}
function loginRequired(){return `<div class="login-gate-curtain" data-action="cancel-login-gate"></div><section class="login-gate" role="dialog" aria-modal="true" aria-labelledby="loginGateTitle"><span>AI 赴港顾问</span><h2 id="loginGateTitle">登录后才能开始对话</h2><p>登录后，AI 才能结合你的企业信息和评估记录提供建议，并保存本次沟通。</p><div><button class="secondary" data-action="cancel-login-gate">暂不登录</button><button class="primary" data-action="login-for-chat">去登录</button></div></section>`}
function home(){const personalized=state.homeData?.mode==='personalized',type=state.homeData?.type||'pre-hk',conclusion=state.homeData?.conclusion||state.homeData?.result?.conclusion||'',content=!state.token?newHome():state.homeLoading?homeLoading():personalized?assessedHome():newHome();return `<section class="page home-page ${personalized?'personalized':''}">${topbar()}<div class="hero"><div class="face idle" aria-label="AI顾问表情"><i></i></div><h1>赴港开公司，AI 帮你规划</h1><p>已帮助 650+ 企业了解赴港开公司的选择</p><div class="askbox"><input id="heroAsk" aria-label="向AI提问" placeholder="问一问  ${type==='in-hk'?'香港公司后续怎么做':'我想在香港开公司'}"><button type="button" data-action="voice-input" data-voice-target="heroAsk" aria-label="开始语音输入" aria-pressed="false">${icons.mic}</button></div><div class="voice-status" role="status" aria-live="polite"></div></div><main class="home-content">${content}${practicalInfo(type,conclusion)}<footer class="home-footer"><div class="footer-mark"><div class="wordmark">赴港通<small>HK PATHWAY</small></div><button data-route="profile" aria-label="打开我的"><span class="face-mini"></span></button></div><button data-route="about"><b>关于我们</b><small>About Us</small><span>→</span></button><button data-route="cooperation"><b>商务合作</b><small>Business Cooperation</small><span>→</span></button><button data-route="contact"><b>联系我们</b><small>Contact Us</small><span>→</span></button></footer></main>${state.profileOpen?profilePanel():''}${state.loginPrompt?loginRequired():''}</section>`}
function login(){const forChat=localStorage.getItem('hk-pending-type')==='chat';return `<section class="page no-nav login-page"><header class="login-nav"><button data-action="back" aria-label="返回">←</button><div><b>登录／注册</b><small>Sign in</small></div><span></span></header><div class="login-banner"><div class="wordmark">赴港通<small>HK PATHWAY</small></div></div><div class="login-body"><div class="login-copy"><h1>${forChat?'登录后咨询 AI 赴港顾问':'继续你的 AI 赴港评估'}</h1><p>${forChat?'登录后，AI 可结合企业信息与评估记录提供建议':'请先登录，完成评估后，可获得与你企业情况匹配的服务资源'}</p></div><form class="login-form" id="loginForm" novalidate><div class="login-field"><label class="sr-only" for="phone">手机号码</label><input id="phone" name="phone" inputmode="numeric" autocomplete="tel" placeholder="手机号码" value="${escape(state.phone)}" required aria-describedby="phoneError"><div id="phoneError" class="field-error"></div></div><div class="login-field code-field"><label class="sr-only" for="code">验证码</label><input id="code" name="code" inputmode="numeric" autocomplete="one-time-code" placeholder="验证码" required aria-describedby="codeError"><button type="button" data-action="fill-demo-code">获取验证码</button><div id="codeError" class="field-error"></div></div><button class="login-submit" type="submit">${forChat?'登录并开始咨询':'登录并开始评估'}</button><p class="login-agreement">登录即表示同意《用户协议》和《隐私政策》</p></form></div></section>`}
function start(type){if(type==='chat'){state.route=state.token?'chat':'login';if(state.token&&!state.chatLoaded)state.chat=readCachedChat(state.token);render();if(state.token)loadChatHistory();return}state.assessmentType=type;state.answers=JSON.parse(localStorage.getItem(`hk-draft-${type}`)||'{}');state.index=0;state.result=null;if(!state.token){state.route='login';localStorage.setItem('hk-pending-type',type);}else state.route='question';render();}
function questions(){return visibleQuestions(state.assessmentType,state.answers)}
function currentQuestion(){const qs=questions();state.index=Math.max(0,Math.min(state.index,qs.length-1));return {q:qs[state.index],qs};}
function optionSelected(q,o){const v=state.answers[q.id];return Array.isArray(v)?v.includes(o):v===o}
function questionHelp(q){if(q.id==='F03')return '可多选，根据企业实际经营范围选择一个或多个地区。';if(q.type==='multi-primary')return `可多选${q.max?`，最多选择 ${q.max} 项`:''}，并确认最主要的一项。`;if(q.type.startsWith('multi'))return `可多选${q.max?`，最多选择 ${q.max} 项`:''}。`;return '请选择最符合实际情况的一项。'}
function needsOther(q,v){return !!q.other&&Array.isArray(v)&&v.includes('其他')}
function questionValid(q,v,primary){return (Array.isArray(v)?v.length>0:!!v)&&(!needsOther(q,v)||!!String(state.answers[q.id+'_other']||'').trim())&&!(q.type==='multi-primary'&&Array.isArray(v)&&v.length>1&&!primary)}
function questionCanContinue(q,v){return (Array.isArray(v)?v.length>0:!!v)&&(!needsOther(q,v)||!!String(state.answers[q.id+'_other']||'').trim())}
function otherInput(q,v){return needsOther(q,v)?`<label class="other-answer"><span>请补充说明</span><input data-other-for="${q.id}" maxlength="${q.other.max}" value="${escape(state.answers[q.id+'_other']||'')}" placeholder="${escape(q.other.placeholder)}"><small>最多 ${q.other.max} 字</small></label>`:''}
function question(){const {q,qs}=currentQuestion();if(!q)return review();const v=state.answers[q.id];const primary=state.answers[q.id+'_primary'],canContinue=questionCanContinue(q,v);return `<section class="page no-nav question-page"><header class="question-nav"><button data-action="back">←　返回</button></header><div class="question-progress"><i style="width:${(state.index+1)/qs.length*100}%"></i></div><div class="question"><span class="kicker">${state.assessmentType==='in-hk'?'了解香港公司':'了解你的业务'}</span><h1>${escape(q.title)}</h1><p>${escape(questionHelp(q))}</p><div class="options">${q.options.map(o=>`<button class="option ${optionSelected(q,o)?'selected':''}" data-option="${escape(o)}" aria-pressed="${optionSelected(q,o)}"><i class="check" aria-hidden="true"></i><span>${escape(o)}</span></button>`).join('')}</div>${otherInput(q,v)}${q.type==='multi-primary'&&Array.isArray(v)&&v.length>1?`<div class="primary-picker"><h3>哪一项是最主要的？</h3><div class="options">${v.map(o=>`<button class="option ${primary===o?'selected':''}" data-primary="${escape(o)}" aria-pressed="${primary===o}"><i class="check" aria-hidden="true"></i><span>${escape(o)}</span></button>`).join('')}</div></div>`:''}</div><div class="bottom-actions"><button class="secondary" data-action="prev-question" ${state.index===0?'disabled':''}>上一步</button><button class="primary" data-action="next-question" ${!canContinue?'disabled':''}>${state.index===qs.length-1?'确认答案':'下一步'}</button></div></section>`}
function editSheet(q){if(!q)return '';const v=state.answers[q.id],primary=state.answers[q.id+'_primary'];return `<div class="sheet-backdrop" data-action="cancel-edit"></div><section class="edit-sheet" role="dialog" aria-modal="true" aria-labelledby="editTitle"><header><div><span>修改选项</span><h2 id="editTitle">${escape(q.title)}</h2></div><button data-action="cancel-edit" aria-label="关闭">×</button></header><div class="sheet-options">${q.options.map(o=>`<button class="option ${optionSelected(q,o)?'selected':''}" data-option="${escape(o)}" aria-pressed="${optionSelected(q,o)}"><i class="check"></i><span>${escape(o)}</span></button>`).join('')}</div>${q.type==='multi-primary'&&Array.isArray(v)&&v.length>1?`<div class="sheet-primary"><h3>哪一项是最主要的？</h3>${v.map(o=>`<button class="option ${primary===o?'selected':''}" data-primary="${escape(o)}"><i class="check"></i><span>${escape(o)}</span></button>`).join('')}</div>`:''}<footer><button class="secondary" data-action="cancel-edit">取消</button><button class="primary" data-action="finish-edit">完成</button></footer></section>`}
function review(){const qs=questions(),editing=state.editingIndex===null?null:qs[state.editingIndex];return `<section class="page no-nav">${topbar('确认信息',true)}<div class="review"><h1>确认一下企业情况</h1><p>以下信息将用于生成你的评估，请确认是否准确。</p><div class="review-group">${qs.map((q,i)=>{let v=state.answers[q.id];if(q.type==='multi-primary'&&state.answers[q.id+'_primary'])v=[`主要：${state.answers[q.id+'_primary']}`,...v.filter(x=>x!==state.answers[q.id+'_primary'])];return `<button class="review-row" data-edit-index="${i}"><span>${escape(q.title.replace(/[？?]$/,''))}</span><b>${escape(Array.isArray(v)?v.join('、'):v||'')}</b><em>编辑</em></button>`}).join('')}</div></div><div class="bottom-actions"><button class="secondary" data-action="back-question">返回修改</button><button class="primary" data-action="submit-assessment" ${state.submitting?'disabled':''}>${state.submitting?'正在提交':'开始评估'}</button></div>${editSheet(editing)}</section>`}
function analysis(){const inHK=state.assessmentType==='in-hk',steps=['读取企业基本情况','识别当前业务阶段','核对跨境需求与目标','检查需要确认的事项','计算评估结论','生成下一步建议'];return `<section class="page no-nav">${topbar('AI评估',false)}<div class="analysis" aria-busy="true">${aiLoader(`正在生成你的${inHK?'在港状态':'赴港'}评估`,'正在核对企业信息，并按照评估规则形成结论')}<div class="analysis-list">${steps.map((s,i)=>`<div class="analysis-step ${i===0?'active':''}" data-analysis-step="${i}"><i></i><span>${s}</span></div>`).join('')}</div><p class="fine analysis-note">结论由确定性规则生成，AI不会修改评分或结论。</p></div></section>`}
const dimLabel=(n,max)=>{const p=n/max*100;return p>=80?'准备充分':p>=60?'基础稳定':p>=40?'需要确认':'尚待准备'};
function radar(d){const vals=[d.compliance/25,d.hkValue/35,d.crossBorder/20,d.business/20];const pts=vals.map((v,i)=>{const a=(-90+i*90)*Math.PI/180;return `${70+Math.cos(a)*52*v},${70+Math.sin(a)*52*v}`}).join(' ');return `<svg class="radar" viewBox="0 0 140 140" role="img" aria-label="企业赴港四维雷达图"><polygon points="70,14 126,70 70,126 14,70"/><polygon points="70,35 105,70 70,105 35,70"/><line x1="70" y1="14" x2="70" y2="126"/><line x1="14" y1="70" x2="126" y2="70"/><polygon class="radar-value" points="${pts}"/></svg>`}
const resultIconMap={'本次判断依据':'why','你的企业赴港情况':'situation','香港公司当前情况':'situation','业务特点':'business','需要进一步确认':'confirm','需要特别关注':'risk','优先处理与待完善事项':'risk','初步公司定位':'building','初步架构方向':'network','下一步建议':'route'};
const resultPlanLabel=r=>(r.type==='in-hk'?{'注册审批中':'查看成立后准备清单','成立待运营':'获取成立后待办清单','当前运行基本正常':'查看日常维护建议','有事项待完善':'查看我的完善清单','需要优先核验':'查看优先处理事项','退出安排待梳理':'查看停止经营准备清单'}:{'适合启动':'制定我的赴港计划','具备基础':'完善我的赴港方案','值得探索':'看看最值得先做什么','早期准备':'获取赴港准备清单'})[r.conclusion]||'查看推荐方案';
function resultCard(title,content){const icon=resultIconMap[title]||'route';if(title==='本次判断依据'&&state.result?.basis)content=`<p>${escape(state.result.basis)}</p>`;if(title==='下一步建议'){const tasks=(state.result?.actions?.length?state.result.actions:['补充交易路径与合规安排','核对公司注册、秘书及持续维护要求','匹配法律和财税专业服务']);content=`<ol class="result-task-list">${tasks.slice(0,3).map((x,i)=>`<li><b>${String(i+1).padStart(2,'0')}</b><span><strong>${escape(x)}</strong><small>${i===0?'现在优先处理':'完成上一项后继续'}</small></span></li>`).join('')}</ol>`}return `<section class="result-card"><h2><img src="/assets/icon-${icon}.svg" alt="">${escape(title)}</h2>${content}</section>`}
function result(){const r=state.result;if(!r)return home();if(r.type==='in-hk')return `<section class="page no-nav result-page">${topbar('评估结果',true)}<div class="result-hero in-hk"><img src="/assets/result-check.svg" alt=""><h1>${escape(r.title)}</h1><p>${escape(r.summary)}</p>${resultCard('本次判断依据',`<p>${escape(r.companyStatus||'根据香港公司的实际运营状态生成结论。')}</p>`,'⌕')}</div><div class="result-content">${resultCard('香港公司当前情况',`<ul>${[r.companyStatus,...r.roles].filter(Boolean).map(x=>`<li>${escape(x)}</li>`).join('')}</ul>`,'◎')}${resultCard('优先处理与待完善事项',`<ul>${(r.issues.length?r.issues:['目前没有明显需要优先处理的事项']).map(x=>`<li>${escape(x)}</li>`).join('')}</ul>`,'△')}${resultCard('下一步建议',`<ul>${(r.actions.length?r.actions:['确认公司成立后的账户、合同、会计记录与持续维护安排']).map(x=>`<li>${escape(x)}</li>`).join('')}</ul>`,'↗')}<div class="result-actions"><button class="primary red" data-route="home">${escape(resultPlanLabel(r))}</button><button class="primary" data-action="open-chat">问问AI</button><button class="text-action" data-action="restart">重新评估</button></div></div></section>`;const d=r.dimensions;return `<section class="page no-nav result-page">${topbar('评估结果',true)}<div class="result-hero"><img src="/assets/result-check.svg" alt=""><h1>${escape(r.title)}</h1><p>${escape(r.summary)}</p>${resultCard('本次判断依据',`<p>${escape(r.conclusion==='具备基础'?'企业已有一定海外业务基础和明确赴港目的，但交易路径与主体分工仍需完善。':r.summary)}</p>`,'⌕')}</div><div class="result-content">${resultCard('你的企业赴港情况',`<p class="card-note">我们从四个方面分析香港是否能为企业带来实际价值。</p><div class="radar-layout"><div class="radar-top"><b>行业及合规</b><span>${dimLabel(d.compliance,25)}</span></div><div class="radar-mid"><div><b>企业业务基础</b><span>${dimLabel(d.business,20)}</span></div>${radar(d)}<div><b>香港发展价值</b><span>${dimLabel(d.hkValue,35)}</span></div></div><div class="radar-bottom"><b>跨境业务需求</b><span>${dimLabel(d.crossBorder,20)}</span></div><p class="radar-note">图形越靠外，表示该维度的准备程度越充分。</p></div>`,'◎')}${resultCard('业务特点',`<ul>${r.features.map(x=>`<li>${escape(x)}</li>`).join('')}</ul>`,'▣')}${resultCard('需要进一步确认',`<p>确认主要交易币种、付款方地区和合同主体，判断香港公司适合承担的角色。</p>`,'?')}${resultCard('需要特别关注',`<p>${escape(r.attention?.length?'围绕 '+r.attention.join('、')+'建立真实合同、订单、交付和资金路径。':'账户安排需要建立在真实合同、订单、交付和资金路径基础上。')}</p>`,'△')}${resultCard('初步公司定位',`<p><b>${escape(r.position)}</b>：围绕真实跨境业务承担相应职能并保留完整业务证明。</p>`,'⌂')}${resultCard('初步架构方向',`<p>先采用单一香港主体承接最明确的跨境业务，需求稳定后再评估增加持股层级。</p>`,'↗')}${resultCard('下一步建议',`<p>先补充交易路径与合规安排，再匹配公司注册、秘书、法律和财税服务。</p>`,'↗')}<div class="result-actions"><button class="primary red" data-route="home">${escape(resultPlanLabel(r))}</button><button class="primary" data-action="open-chat">问问AI</button><button class="text-action" data-action="restart">重新评估</button></div></div></section>`}
function chat(){const initial=state.result?`我已经看过你的“${state.result.conclusion}”评估。你可以问我为什么得到这个结论，或现在最应该先做什么。`:'告诉我你的业务目标，我会帮你梳理适合的赴港路径。';if(!state.chat.length){state.chat.push({id:'welcome',role:'assistant',content:initial,createdAt:Date.now()});persistChat()}const bubbles=state.chat.flatMap(m=>(m.role==='assistant'?splitAssistantReply(m.content):[m.content]).map(content=>({...m,content})));return `<section class="page no-nav chat-page">${topbar('AI赴港顾问',true)}<div class="chat-log" id="chatLog" aria-live="polite">${bubbles.map(m=>`<div class="bubble ${m.role==='user'?'user':'assistant'}">${chatMessageHtml(m)}</div>`).join('')}${state.chatLoading?'<div class="chat-history-loading">正在同步历史对话…</div>':''}${state.submitting?'<div class="bubble assistant thinking-bubble" role="status"><i></i><i></i><i></i><span class="sr-only">AI正在思考</span></div>':''}</div><div class="chat-voice-status voice-status" role="status" aria-live="polite"></div><form class="chat-compose" id="chatForm"><button class="chat-voice" type="button" data-action="voice-input" data-voice-target="chatMessage" aria-label="开始语音输入" aria-pressed="false" ${state.submitting?'disabled':''}>${icons.mic}</button><input id="chatMessage" name="message" aria-label="输入问题" placeholder="${state.submitting?'AI 正在思考…':'输入你想了解的问题'}" required ${state.submitting?'disabled':''}><button class="chat-send" type="submit" aria-label="发送消息" ${state.submitting?'disabled':''}>${icons.send}</button></form></section>`}
async function loadChatHistory(){if(!state.token||state.chatLoading||state.chatLoaded)return;state.chatLoading=true;if(state.route==='chat')render();try{const d=await api('/api/chat/history');const cloud=Array.isArray(d.messages)?d.messages:[],local=state.chat.filter(m=>String(m.id||'').startsWith('local-')||String(m.id||'').endsWith('-error')||(!cloud.length&&m.id==='welcome'));const merged=[...cloud,...local].filter((m,index,all)=>all.findIndex(x=>x.id===m.id)===index).sort((a,b)=>(a.createdAt||0)-(b.createdAt||0));if(merged.length)state.chat=merged;state.chatLoaded=true;persistChat()}catch{state.chatLoaded=true}finally{state.chatLoading=false;if(state.route==='chat'){render();requestAnimationFrame(()=>document.querySelector('#chatLog')?.scrollTo({top:999999}))}}}
async function sendChatMessage(msg){if(!msg||state.submitting)return;const requestId=crypto.randomUUID?.()||`${Date.now()}${Math.random()}`,temporaryId=`local-${requestId}`;state.chat.push({id:temporaryId,role:'user',content:msg,createdAt:Date.now()});persistChat();state.submitting=true;render();const scroll=()=>requestAnimationFrame(()=>document.querySelector('#chatLog')?.scrollTo({top:999999,behavior:'smooth'}));scroll();try{const d=await api('/api/chat',{method:'POST',body:JSON.stringify({message:msg,requestId,context:{result:state.result},history:state.chat})});state.chat=state.chat.filter(m=>m.id!==temporaryId);if(d.messages?.length)state.chat.push(...d.messages);else state.chat.push({id:`${requestId}-u`,role:'user',content:msg,createdAt:Date.now()},{id:`${requestId}-a`,role:'assistant',content:d.reply,createdAt:Date.now()+1});persistChat();render();scroll()}catch(err){state.chat.push({id:`${requestId}-error`,role:'assistant',content:err.message||'暂时无法连接AI，请稍后重试。',createdAt:Date.now()+1});persistChat()}finally{state.submitting=false;render();scroll()}}
function profile(){return `<section class="page no-nav">${topbar('',true)}<h1 class="page-heading">我的</h1>${state.phone?`<div class="profile-head"><span class="avatar">${escape(state.phone.slice(-1))}</span><div><b>${escape(state.phone.slice(0,3)+' **** '+state.phone.slice(-4))}</b><p>企业信息已与账号关联</p></div></div><div class="profile-list"><button data-route="account"><b>账号资料</b><span>手机、称呼与语言偏好　→</span></button><button data-route="company"><b>企业信息表</b><span>查看和编辑已确认的信息　→</span></button><button data-route="assessments"><b>我的评估与计划</b><span>${state.result?'已有 1 份评估结果':'暂无评估'}　→</span></button><button data-route="favorites"><b>收藏的服务商</b><span>查看收藏与比较列表　→</span></button><button data-route="about"><b>关于公司</b><span>About HK Pathway　→</span></button><button data-route="cooperation"><b>商务合作</b><span>服务商与机构合作　→</span></button><button data-route="contact"><b>联系我们</b><span>服务时间与问题反馈　→</span></button></div><div class="content"><button class="secondary" data-action="logout">退出登录</button></div>`:'<div class="empty"><p>登录后查看企业信息、评估记录和收藏内容。</p><button class="primary" data-route="login">去登录</button></div>'}</section>`}
function simplePage(title,body){return `<section class="page no-nav">${topbar(title,true)}<div class="detail-page">${body}</div></section>`}
function guide(){const g=state.selectedGuide;if(!g)return simplePage('指南详情','<div class="empty"><p>未找到这篇指南。</p></div>');return `<section class="page no-nav guide-page">${topbar('指南详情',true)}<article class="guide-detail"><img src="${escape(g.cover)}" alt=""><span>${escape(g.type==='in-hk'?'在港经营指南':'赴港指南')}</span><h1>${escape(g.title)}</h1><p class="guide-source">信息来源：${escape(g.source)}</p><section><h2>这篇内容可以帮你了解</h2><p>${escape(g.description)}</p></section><section><h2>为什么推荐给你</h2><p>${escape(g.type==='in-hk'?'根据你最近一次在港状态评估的结论，这篇内容与公司当前阶段需要处理的事项相关。':'根据你最近一次赴港评估的结论，这篇内容与你当前需要了解的设立、经营或合规事项相关。')}</p></section><a href="${escape(g.url)}" target="_blank" rel="noopener noreferrer">查看官方原文 ↗</a><small>你将前往${escape(g.source)}官方网站</small></article></section>`}
function account(){const name=localStorage.getItem('hk-display-name')||'未填写';return simplePage('账号资料',`<h1>账号资料</h1><form id="accountForm" class="account-form ${state.accountEditing?'is-editing':''}"><div class="form-table"><label>手机号码<b>${escape(state.phone||'未登录')}</b></label><label>姓名／称呼${state.accountEditing?`<input id="displayName" name="displayName" maxlength="30" value="${escape(name==='未填写'?'':name)}" placeholder="请输入希望使用的称呼">`:`<b>${escape(name)}</b>`}</label><label>所在地区<b>中国内地</b></label><label>语言偏好<b>简体中文</b></label></div>${state.accountEditing?`<div class="account-actions"><button class="secondary" type="button" data-action="cancel-account-edit">取消</button><button class="primary" type="submit">保存</button></div>`:`<button class="secondary" type="button" data-action="edit-account">编辑资料</button>`}</form>`)}
function companyData(){const a=state.result?.answers||{},saved=JSON.parse(localStorage.getItem('hk-company-profile')||'{}');return {industry:saved.industry||a.F01_primary||a.F01?.[0]||'',location:saved.location||(a.F03||[]).join('、')||'',stage:saved.stage||a.F04||'',scale:saved.scale||a.F12||'',goal:saved.goal||a.F10_primary||''}}
function company(){const c=companyData(),field=(label,name,value,placeholder)=>`<label><span>${label}</span>${state.companyEditing?`<input name="${name}" maxlength="80" value="${escape(value)}" placeholder="${placeholder}">`:`<b>${escape(value||'待补充')}</b>`}</label>`;return simplePage('企业信息表',`<h1>企业信息表</h1><p>来自评估和 AI 对话中经你确认的有效信息，可自行修改。</p><form id="companyForm" class="company-form ${state.companyEditing?'is-editing':''}"><div class="form-table">${field('主营行业','industry',c.industry,'请输入主营行业')}${field('主要经营地','location',c.location,'请输入主要经营地')}${field('当前阶段','stage',c.stage,'请输入当前阶段')}${field('团队规模','scale',c.scale,'请输入团队规模')}${field('赴港主要目标','goal',c.goal,'请输入赴港主要目标')}</div>${state.companyEditing?`<div class="account-actions"><button class="secondary" type="button" data-action="cancel-company-edit">取消</button><button class="primary" type="submit">保存</button></div>`:`<button class="primary" type="button" data-action="edit-company">编辑企业信息</button>`}</form>`)}
function assessments(){const r=state.homeData?.result||state.result,hasResult=state.homeData?.mode==='personalized'&&r;return simplePage('我的评估与计划',hasResult?`<h1>最近一次评估</h1><article class="saved-result"><span>${escape(r.conclusion)}</span><h2>${escape(r.title)}</h2><p>${escape(r.summary)}</p><button class="primary" data-route="result">查看评估结果</button></article><div class="assessment-history-actions"><button class="secondary" data-start="pre-hk">重新进行赴港评估</button><button class="secondary" data-start="in-hk">进行在港评估</button></div>`:`<div class="assessment-empty"><p>还没有评估记录。请选择与你当前情况对应的评估。</p><article><span>AI 赴港评估</span><h2>准备开香港公司</h2><p>了解企业目标、跨境业务和赴港需求。</p><button class="primary" data-start="pre-hk">开始赴港评估</button></article><article><span>在港经营支持</span><h2>已有香港公司</h2><p>检查公司维护、财税、账户和经营事项。</p><button class="primary" data-start="in-hk">开始在港评估</button></article></div>`)}
function provider(){const p=state.selectedProvider;if(!p)return simplePage('服务商详情','<div class="empty"><p>未找到服务商信息。</p></div>');const name=p['服务商简称']||p['服务商名称'],site=p['官方网站']?.link||p['官方网站']||'';return `<section class="page no-nav provider-page">${topbar('服务商详情',true)}<div class="provider-detail"><div class="provider-identity"><span>${escape(name.slice(0,1).toUpperCase())}</span><div><small>${escape((p['服务商类型']||[]).join(' · '))}</small><h1>${escape(name)}</h1></div></div><p>${escape(p['服务商简介']||'')}</p><section><h2>可提供的服务</h2><div class="provider-tags">${(p['可提供服务']||[]).map(x=>`<span>${escape(x)}</span>`).join('')}</div></section><section><h2>适合的企业</h2><dl><div><dt>企业规模</dt><dd>${escape((p['适合企业规模']||[]).join('、')||'未说明')}</dd></div><div><dt>经营阶段</dt><dd>${escape((p['适合经营阶段']||[]).join('、')||'未说明')}</dd></div><div><dt>服务语言</dt><dd>${escape((p['服务语言']||[]).join('、')||'未说明')}</dd></div><div><dt>资质核验</dt><dd>${escape(p['资质核验状态']||'待核验')}</dd></div></dl></section><section><h2>服务说明</h2><p>${escape(p['服务内容说明']||'')}</p>${p['不包含的服务']?`<h3>不包含的服务</h3><p>${escape(p['不包含的服务'])}</p>`:''}</section>${site?`<a class="provider-site" href="${escape(site)}" target="_blank" rel="noopener">前往官方网站 ↗</a>`:''}<p class="provider-disclaimer">服务内容与资质信息来自服务商资料库，请以服务商官网和正式沟通为准。</p></div></section>`}
function favorites(){return simplePage('收藏的服务商',`<h1>收藏的服务商</h1><div class="empty"><p>暂未收藏服务商。完成评估后，可从专属推荐中收藏和比较。</p></div>`)}
function about(){return `<section class="page no-nav about-page">${topbar('',true)}<div class="about-content"><div class="about-title"><b>关于我们</b><span>About Us</span></div><div class="about-brand">赴港通<small>HK PATHWAY</small></div><section><h2>我们是谁</h2><p>赴港通服务计划进入香港市场的内地企业。我们通过 AI 帮助企业看懂赴港要求、判断是否适合设立香港公司，并梳理下一步行动。</p><h2>Who We Are</h2><p>HK Pathway supports Mainland businesses entering Hong Kong. Using AI, we help companies understand the requirements, assess whether a Hong Kong company is right for them, and identify their next steps.</p></section><div class="about-ai"><small>从企业情况出发</small><b>AI 评估&nbsp; → &nbsp;赴港方案<br><i>→ &nbsp;专业服务</i></b></div><section><h2>我们提供什么</h2><p>从企业实际情况出发，提供赴港评估、公司方案、成本与材料计划及官方服务导航；需要专业协助时，帮助筛选公司注册、法律、会计、税务及跨境服务机构。</p><h2>What We Offer</h2><p>We provide market-entry assessments, company setup plans, cost and document guidance, and access to official resources. When professional support is needed, we help businesses discover suitable providers.</p></section><div class="about-services">${['公司注册','法律咨询','会计税务','公司秘书','银行开户','跨境服务'].map(x=>`<span>${x}</span>`).join('')}</div><section><h2>我们的角色</h2><p>赴港通不是香港政府服务平台或专业机构的替代。我们帮助企业理解信息、形成初步判断，并连接相关官方入口与专业服务资源。</p><h2>Our Role</h2><p>HK Pathway does not replace government platforms or professional advisers. We help businesses understand information, form an initial view, and connect with relevant official services and professional support.</p></section></div></section>`}
function cooperation(){return simplePage('商务合作',`<span class="label">BUSINESS COOPERATION</span><h1>连接优质赴港服务</h1><p>面向 TCSP、法律、会计税务、银行及企业经营服务机构开放合作。</p><button class="primary">提交合作意向</button>`)}
function contact(){return simplePage('联系我们',`<span class="label">CONTACT US</span><h1>需要帮助？联系我们</h1><p>工作日 09:30—18:30。演示阶段的官方邮箱与电话待正式确认。</p><button class="primary">提交问题反馈</button>`)}
let idleFaceIndex=0,recognition=null,voiceStatusTimer=null;
let lastViewKey='';
const faceStates=['idle','glance-left','idle','glance-right','idle'];
function setFace(name){const face=document.querySelector('.hero .face');if(face){face.className=`face ${name}`;face.setAttribute('aria-label',`AI顾问表情：${name}`)}}
function voiceInput(button){
 const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;
 const status=button.closest('.hero')?.querySelector('.voice-status')||document.querySelector('.chat-voice-status');
 const setStatus=(message,kind='active',linger=0)=>{if(!status)return;clearTimeout(voiceStatusTimer);status.className=`${status.classList.contains('chat-voice-status')?'chat-voice-status ':''}voice-status ${kind}`;status.innerHTML=kind==='active'?`<i></i><i></i><i></i><span>${message}</span>`:`<span>${message}</span>`;if(linger)voiceStatusTimer=setTimeout(()=>{status.textContent='';status.classList.remove('active','error','success')},linger)};
 if(!Speech){setStatus('当前浏览器暂不支持语音输入','error',3200);toast('当前浏览器暂不支持语音输入');return}
 if(button.classList.contains('recording')){setStatus('正在结束并识别…','active');recognition?.stop();return}
 recognition?.abort();
 recognition=new Speech();recognition.lang='zh-CN';recognition.interimResults=true;recognition.continuous=false;
 const target=document.getElementById(button.dataset.voiceTarget||'heroAsk');
 let receivedResult=false,failed=false;
 const resetButton=()=>{button.classList.remove('recording');button.setAttribute('aria-pressed','false');button.setAttribute('aria-label','开始语音输入');setFace('idle')};
 setFace('listening');button.classList.add('recording');button.setAttribute('aria-pressed','true');button.setAttribute('aria-label','停止语音输入');setStatus('正在连接麦克风…','active');
 recognition.onstart=()=>setStatus('正在收音，再次点击麦克风结束','active');
 recognition.onaudiostart=()=>setStatus('正在收音，再次点击麦克风结束','active');
 recognition.onspeechstart=()=>setStatus('已检测到声音，正在识别…','active');
 recognition.onresult=e=>{const text=[...e.results].map(x=>x[0].transcript).join('').trim();if(text){receivedResult=true;if(target){target.value=text;target.dispatchEvent(new Event('input',{bubbles:true}))}setStatus('已识别为文字','success',2200)}};
 recognition.onerror=e=>{failed=true;const messages={'not-allowed':'麦克风权限未开启，请在浏览器设置中允许','service-not-allowed':'浏览器未允许使用语音服务','audio-capture':'未检测到可用麦克风','network':'语音服务连接失败，请检查网络','no-speech':'未检测到声音，请靠近麦克风再试','aborted':'语音输入已取消'};const message=messages[e.error]||'语音输入暂时不可用，请重试';resetButton();setStatus(message,'error',3600);toast(message)};
 recognition.onend=()=>{resetButton();if(failed)return;if(receivedResult)setStatus('已识别为文字','success',2200);else setStatus('未检测到声音，请靠近麦克风再试','error',3600)};
 try{recognition.start()}catch{failed=true;resetButton();setStatus('语音输入暂时不可用，请重试','error',3600);toast('语音输入暂时不可用，请重试')}
}
function render(preserveScroll=false){const previousScroll=app.scrollTop,viewKey=state.route==='question'?`question:${state.index}`:state.route,entering=viewKey!==lastViewKey;const routes={home,login,question,review,analysis,result,chat,profile,account,company,assessments,favorites,provider,guide,about,cooperation,contact};app.innerHTML=(routes[state.route]||home)();app.classList.toggle('modal-open',state.editingIndex!==null);if(entering)app.querySelector('.page')?.classList.add('page-enter');lastViewKey=viewKey;if(state.route==='result'&&state.result){const hero=app.querySelector('.result-hero'),tag=document.createElement('span');tag.className='conclusion-tag';tag.textContent=state.result.conclusion;hero?.querySelector('img')?.after(tag)}if(preserveScroll){const restore=()=>{app.scrollTop=previousScroll};requestAnimationFrame(()=>{restore();requestAnimationFrame(restore);setTimeout(restore,80)})}else{app.scrollTop=0;window.scrollTo(0,0)}}
async function loadHome(force=false,preferredType=''){if(!state.token||state.homeLoading||state.homeData&&!force)return;state.homeLoading=true;if(['home','assessments'].includes(state.route))render();const type=['pre-hk','in-hk'].includes(preferredType)?preferredType:'';try{state.homeData=await api(`/api/home${type?`?type=${type}`:''}`);if(state.homeData?.assessmentType)state.assessmentType=state.homeData.assessmentType;if(state.homeData?.result){state.result=state.homeData.result;localStorage.setItem('hk-latest-result',JSON.stringify(state.result))}}catch(err){if(err.message==='请先登录'){localStorage.removeItem('hk-token');state.token=''}else toast('暂时无法读取最新评估')}finally{state.homeLoading=false;if(['home','assessments'].includes(state.route))render()}}
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='cancel-login-gate'){e.preventDefault();e.stopImmediatePropagation();state.loginPrompt=false;render();return}if(action==='login-for-chat'){e.preventDefault();e.stopImmediatePropagation();state.loginPrompt=false;localStorage.setItem('hk-pending-type','chat');state.returnRoute='home';state.route='login';render();return}if(!state.token&&(action==='voice-input'||action==='ask-home'||action==='open-chat')){e.preventDefault();e.stopImmediatePropagation();state.loginPrompt=true;render()}},true);
document.addEventListener('click',e=>{
 const action=e.target.closest('[data-action]')?.dataset.action;
 if(action==='back'&&state.route==='chat'){
  e.preventDefault();e.stopImmediatePropagation();state.returnRoute='home';state.route='home';render();loadHome();return;
 }
 if(action==='logout'){state.chat=[];state.chatLoaded=false;state.chatLoading=false;return}
 if(state.token&&(action==='ask-home'||action==='open-chat')){if(!state.chatLoaded)state.chat=readCachedChat(state.token);setTimeout(loadChatHistory,0)}
},true);
document.addEventListener('click',e=>{const primary=e.target.closest('[data-primary]');if(primary){e.preventDefault();e.stopImmediatePropagation();state.answers[currentQuestion().q.id+'_primary']=primary.dataset.primary;render(true)}},true);
document.addEventListener('click',e=>{const button=e.target.closest('[data-guide-index]');if(!button)return;e.preventDefault();e.stopImmediatePropagation();const type=button.dataset.guideType,conclusion=button.dataset.guideConclusion,inHK=type==='in-hk',items=(inHK?inGuides[conclusion]:preGuides[conclusion])||(inHK?inGuides['成立待运营']:preGuides['适合启动']),item=items[Number(button.dataset.guideIndex)];if(!item)return;state.selectedGuide={title:item[0],source:item[1],url:item[2],description:guideDescriptions[item[0]]||'查看与当前评估阶段相关的官方说明和办理要求。',cover:button.querySelector('img')?.getAttribute('src')||'/assets/guide-prepare.svg',type};state.returnRoute='home';state.route='guide';render()},true);
document.addEventListener('click',async e=>{const providerButton=e.target.closest('[data-provider-id]');if(providerButton){state.returnRoute='home';try{const d=await api('/api/providers/'+encodeURIComponent(providerButton.dataset.providerId));state.selectedProvider=d.provider;state.route='provider';render()}catch(err){toast(err.message)}return}const route=e.target.closest('[data-route]');if(route){if(route.dataset.route==='profile'&&state.route==='home'){state.profileOpen=true;render();return}const completedType=state.route==='result'?state.result?.type:'';state.profileOpen=false;state.returnRoute=state.route;state.route=route.dataset.route;render();if(state.route==='home'&&state.homeData?.mode!=='personalized')loadHome(true,completedType);if(state.route==='assessments')loadHome(!state.homeData);return}const startBtn=e.target.closest('[data-start]');if(startBtn){start(startBtn.dataset.start);return}const a=e.target.closest('[data-action]');if(a){const action=a.dataset.action;if(action==='close-profile'){state.profileOpen=false;render()}if(action==='edit-account'){state.accountEditing=true;render();requestAnimationFrame(()=>document.querySelector('#displayName')?.focus())}if(action==='cancel-account-edit'){state.accountEditing=false;render()}if(action==='edit-company'){state.companyEditing=true;render();requestAnimationFrame(()=>document.querySelector('#companyForm input')?.focus())}if(action==='cancel-company-edit'){state.companyEditing=false;render()}if(action==='back'){state.accountEditing=false;state.companyEditing=false;state.route=state.route==='question'?'home':state.route==='review'?'question':state.route==='chat'?(state.result?'result':'home'):state.returnRoute||'home';state.returnRoute='home';render();if(state.route==='home')loadHome()}if(action==='assessment-hub')start('pre-hk');if(action==='service-toast')toast('该服务将在服务商数据库完成后开放');if(action==='voice-input')voiceInput(a);if(action==='ask-home'||action==='open-chat'){state.returnRoute=state.route;state.route='chat';render()}if(action==='prev-question'){state.index--;render()}if(action==='back-question'){state.index=Math.max(0,questions().length-1);state.route='question';render()}if(action==='next-question'){const {q,qs}=currentQuestion();if(q.skip&&q.skip(state.answers))state.answers[q.id]=q.autoValue;if(state.index>=qs.length-1){state.route='review'}else state.index++;localStorage.setItem(`hk-draft-${state.assessmentType}`,JSON.stringify(state.answers));render()}if(action==='submit-assessment')submitAssessment();if(action==='restart'){localStorage.removeItem(`hk-draft-${state.assessmentType}`);start(state.assessmentType)}if(action==='logout'){localStorage.removeItem('hk-token');localStorage.removeItem('hk-phone');localStorage.removeItem('hk-latest-result');state.token='';state.phone='';state.result=null;state.homeData=null;state.profileOpen=false;state.route='home';render()}}const opt=e.target.closest('[data-option]');if(opt){selectOption(currentQuestion().q,opt.dataset.option)}const primary=e.target.closest('[data-primary]');if(primary){state.answers[currentQuestion().q.id+'_primary']=primary.dataset.primary;render()}const edit=e.target.closest('[data-edit-index]');if(edit){state.index=Number(edit.dataset.editIndex);state.route='question';render()}});
document.addEventListener('click',e=>{if(e.target.closest('[data-action="fill-demo-code"]')){const code=document.querySelector('#code');if(code){code.value='888888';code.focus();toast('演示验证码已填入')}}});
document.addEventListener('focusin',e=>{if(e.target.id==='heroAsk'&&!state.token){e.target.blur();state.loginPrompt=true;render()}},true);
document.addEventListener('focusin',e=>{if(e.target.id==='heroAsk')setFace('looking')});
document.addEventListener('focusout',e=>{if(e.target.id==='heroAsk')setFace('idle')});
document.addEventListener('keydown',e=>{if(e.target.id==='heroAsk'&&e.key==='Enter'&&e.target.value.trim()){e.preventDefault();if(!state.token){state.loginPrompt=true;render();return}const msg=e.target.value.trim();state.returnRoute='home';state.route='chat';sendChatMessage(msg)}});
document.addEventListener('click',e=>{const edit=e.target.closest('[data-edit-index]'),action=e.target.closest('[data-action]')?.dataset.action;if(edit){e.preventDefault();e.stopImmediatePropagation();state.editingBackup=JSON.parse(JSON.stringify(state.answers));state.editingIndex=Number(edit.dataset.editIndex);state.index=state.editingIndex;render();return}if(state.editingIndex!==null&&(action==='cancel-edit'||action==='finish-edit')){e.preventDefault();e.stopImmediatePropagation();if(action==='cancel-edit')state.answers=state.editingBackup;else localStorage.setItem(`hk-draft-${state.assessmentType}`,JSON.stringify(state.answers));state.editingIndex=null;state.editingBackup=null;render()}},true);
document.addEventListener('click',e=>{if(e.target.closest('[data-action="next-question"]')){const q=currentQuestion().q,v=state.answers[q?.id];if(q?.type==='multi-primary'&&Array.isArray(v)&&v.length>1&&!state.answers[q.id+'_primary']){e.preventDefault();e.stopImmediatePropagation();const picker=document.querySelector('.primary-picker');picker?.classList.add('needs-answer');picker?.scrollIntoView({behavior:'smooth',block:'center'});toast('请选择最主要的一项')}}},true);
function selectOption(q,o){if(q.type==='single'){state.answers[q.id]=o;if(q.id==='F04'&&o==='筹备中')state.answers.F05='尚未开始经营'}else{let v=[...(state.answers[q.id]||[])];const exclusive=(q.exclusive||[]).includes(o);if(v.includes(o))v=v.filter(x=>x!==o);else{if(exclusive)v=[o];else{v=v.filter(x=>!(q.exclusive||[]).includes(x));if(q.max&&v.length>=q.max)return toast(`最多选择 ${q.max} 项，请先取消一项`);v.push(o)}}state.answers[q.id]=v;if(!v.includes('其他'))delete state.answers[q.id+'_other'];if(q.type==='multi-primary'){const pk=q.id+'_primary';if(!v.includes(state.answers[pk]))state.answers[pk]=''}}render(true)}
document.addEventListener('input',e=>{const id=e.target.dataset.otherFor;if(!id)return;state.answers[id+'_other']=e.target.value;const q=currentQuestion().q,next=document.querySelector('[data-action="next-question"]');if(q&&next)next.disabled=!questionValid(q,state.answers[q.id],state.answers[q.id+'_primary']);localStorage.setItem(`hk-draft-${state.assessmentType}`,JSON.stringify(state.answers))});
document.addEventListener('submit',async e=>{if(e.target.id!=='accountForm')return;e.preventDefault();e.stopImmediatePropagation();if(!state.accountEditing)return;const name=new FormData(e.target).get('displayName').trim();if(!name)return toast('请输入姓名或称呼');const submit=e.target.querySelector('[type="submit"]');submit.disabled=true;submit.textContent='保存中…';try{await api('/api/account',{method:'POST',body:JSON.stringify({displayName:name})});localStorage.setItem('hk-display-name',name);state.accountEditing=false;render();toast('账号资料已保存')}catch(err){submit.disabled=false;submit.textContent='保存';toast(err.message)}},true);
document.addEventListener('submit',async e=>{if(e.target.id!=='companyForm')return;e.preventDefault();e.stopImmediatePropagation();if(!state.companyEditing)return;const fd=new FormData(e.target),profile=Object.fromEntries(['industry','location','stage','scale','goal'].map(k=>[k,String(fd.get(k)||'').trim()]));if(!profile.industry)return toast('请填写主营行业');const submit=e.target.querySelector('[type="submit"]');submit.disabled=true;submit.textContent='保存中…';try{await api('/api/company',{method:'POST',body:JSON.stringify(profile)});localStorage.setItem('hk-company-profile',JSON.stringify(profile));state.companyEditing=false;render();toast('企业信息已保存')}catch(err){submit.disabled=false;submit.textContent='保存';toast(err.message)}},true);
document.addEventListener('submit',async e=>{e.preventDefault();if(e.target.id==='loginForm'){const fd=new FormData(e.target),phone=fd.get('phone').trim(),code=fd.get('code').trim();const pe=document.querySelector('#phoneError'),ce=document.querySelector('#codeError');pe.textContent=/^1\d{10}$/.test(phone)?'':'请输入11位手机号';ce.textContent=code?'':'请输入验证码';if(pe.textContent||ce.textContent)return;try{const d=await api('/api/login',{method:'POST',body:JSON.stringify({phone,code,companyStatus:localStorage.getItem('hk-pending-type')||'pre-hk'})});state.token=d.token;state.phone=phone;localStorage.setItem('hk-token',d.token);localStorage.setItem('hk-phone',phone);const pending=localStorage.getItem('hk-pending-type')||'pre-hk';localStorage.removeItem('hk-pending-type');start(pending)}catch(err){ce.textContent=err.message}}if(e.target.id==='chatForm'){const input=e.target.elements.message,msg=input.value.trim();if(!msg)return;input.value='';await sendChatMessage(msg)}});
async function submitAssessment(){if(state.submitting)return;state.submitting=true;state.route='analysis';render();document.querySelectorAll('[data-analysis-step]').forEach((el,i)=>setTimeout(()=>{el.classList.remove('active');el.classList.add('done');const next=document.querySelector(`[data-analysis-step="${i+1}"]`);if(next)next.classList.add('active')},350*(i+1)));try{const d=await api(`/api/assess/${state.assessmentType}`,{method:'POST',body:JSON.stringify({answers:state.answers})});await new Promise(r=>setTimeout(r,2200));state.result=d.result;state.homeData=d.home||null;localStorage.setItem('hk-latest-result',JSON.stringify(state.result));localStorage.removeItem(`hk-draft-${state.assessmentType}`);state.route='result';if(!d.saved&&d.saveError)toast('评估已生成，飞书保存稍后重试')}catch(err){toast(err.message);state.route='review'}finally{state.submitting=false;render()}}
render();
