setInterval(()=>{if(state.route==='home'&&document.activeElement?.id!=='heroAsk'&&!document.querySelector('.recording'))setFace(faceStates[++idleFaceIndex%faceStates.length])},3200);
const tokenUserId=()=>userIdFromToken(state.token);
new MutationObserver(()=>{const id=tokenUserId();if(!id)return;document.querySelectorAll('.profile-head').forEach(el=>{if(el.querySelector('.profile-user-id'))return;const line=document.createElement('small');line.className='profile-user-id';line.textContent=`用户ID ${id}`;el.querySelector('div')?.append(line)})}).observe(app,{childList:true,subtree:true});
